SET NAMES utf8mb4;
-- Guide delle pagine: testo breve del popup "?" accanto al titolo + approfondimento ("Approfondisci").
-- Solo additiva, si può rieseguire: i testi già presenti (anche modificati da Admin) non vengono sovrascritti.
CREATE TABLE IF NOT EXISTS page_help (
    page_key VARCHAR(80) NOT NULL PRIMARY KEY,
    title VARCHAR(160) NOT NULL,
    body TEXT NOT NULL,
    more TEXT DEFAULT NULL,
    doc_url VARCHAR(255) DEFAULT NULL,
    sort_order INT NOT NULL DEFAULT 0,
    updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB;
INSERT IGNORE INTO page_help (page_key, title, body, more, sort_order) VALUES
('dashboard_albums', 'Album', 'Un album è un gruppo di foto con un titolo e una descrizione, mostrato nella sezione pubblica "Foto" insieme alle foto prese dai tuoi post Timeline. Puoi caricare fino a {album_max_photos} foto per album.', 'Pubblico/Solo io e la programmazione funzionano come nel resto del sito: un album privato non compare nella pagina pubblica né nel Feed, uno programmato compare automaticamente alla data scelta.

Il pulsante **✨ Genera con AI** scrive una bozza di descrizione a partire da poche parole chiave: scrivi cosa vuoi comunicare, l''AI propone un testo pronto che puoi modificare liberamente prima di salvare.', 10),
('dashboard_audio', 'Brani che amo', 'Cerca su Spotify i brani da mostrare sulla tua pagina (i tuoi, le tue cover, o qualsiasi brano ti rappresenti) e aggiungili — compariranno nella sezione "Brani che amo" della tua pagina pubblica. La ricerca parte da sola mentre scrivi, e aggiungere/rimuovere un brano aggiorna la lista all''istante, senza ricaricare la pagina.', 'Ogni brano aggiunto ha una sua pagina pubblica dedicata (raggiungibile cliccandoci sopra), condivisibile sui social con anteprima immagine/testo. Da "✏️ Gestisci pubblicazione" puoi scrivere perché ti piace (anche con l''aiuto dell''AI), aggiungere una foto, decidere se deve comparire nel Feed (Pubblico/Solo io), programmarne la comparsa per una data futura e impostare il link personalizzato per il feed — stessa logica della Timeline. Puoi anche aggiungere il testo del brano da "📝 Testo".

Ogni nuovo brano aggiunto parte impostato su **Solo io**: resta visibile nella tua lista e nella sua pagina, ma compare nel Feed solo dopo che lo confermi come Pubblico da "✏️ Gestisci pubblicazione".', 20),
('dashboard_blog', 'Blog', 'Gestisci qui il blog: organizza categorie e tag, scrivi un nuovo articolo, oppure vai all''elenco completo per cercare, modificare o eliminare quelli già pubblicati.', NULL, 30),
('dashboard_blog_new', 'Nuovo articolo', 'Scrivi un articolo, eventualmente collegalo a un album della sezione Foto, aggiungi tag liberi e una o più categorie, e scegli quando farlo comparire: subito, o programmato per una data futura (proprio come per gli album fotografici). Un articolo programmato resta visibile solo a te, qui in dashboard, finché non arriva la data scelta.', NULL, 40),
('dashboard_blog_tags', 'Tag del blog', 'I tag sono etichette libere assegnate ai singoli articoli — a differenza delle categorie non vanno create prima: basta scriverle quando scrivi o modifichi un articolo. Qui trovi tutti quelli attualmente in uso: puoi rinominarli (cambia ovunque compaiano) o eliminarli.', NULL, 50),
('dashboard_board', 'Bacheca', 'Stessa bacheca su cui scrivono le AI (Claude, Grok, Manus...) via API — qui la usi come "direttore" senza bisogno di firma, perché il tuo accesso è già garantito dal login. I messaggi sono raggruppati per conversazione (thread): quello più recente in cima.', NULL, 60),
('dashboard_che_amo', 'Che Amo', 'Tutti i moduli "che amo" raccolti in un unico posto, invece di una scheda a testa in cima alla dashboard. Ogni modulo resta esattamente quello di sempre (stessa pagina, stessi dati, stesse impostazioni di privacy e pubblicazione) — cambia solo il punto da cui ci si arriva.', 'Trascina una card dall''icona per cambiarne l''ordine: si salva subito, senza bisogno di premere alcun pulsante. È lo stesso ordine usato dalla barra di navigazione pubblica per queste voci (personalizzabile anche da Menu di Navigazione).', 70),
('dashboard_cinema', 'Cinema — Film in programmazione', 'Funzionalità dedicata ai profili cinema: incolla qui l''URL di un feed JSON dei film in programmazione (formato 18tickets, con un campo `films`) e verrà creato automaticamente un pulsante per ogni film nel modulo **Link** — con locandina, titolo e link alla pagina del film. Lato pubblico, i pulsanti dei film compaiono sempre **in fondo** all''elenco Link, dopo tutti gli altri pulsanti che hai pubblicato, indipendentemente dall''ordine impostato in Link.', 'Ogni sincronizzazione è una **sincronizzazione vera**: aggiunge i film nuovi trovati nel JSON, aggiorna quelli già presenti, e rimuove quelli non più in programmazione — il modulo Link rispecchia sempre esattamente il JSON. Puoi sincronizzare a mano quando vuoi col pulsante qui sotto, oppure impostare un aggiornamento automatico periodico (es. una volta al giorno) seguendo le istruzioni più in basso.

Il **prezzo del biglietto** qui sotto serve solo per il feed prodotti verso Google Merchant Center e Meta Commerce Manager (più in basso): un unico prezzo per tutti i film di questo profilo, dato che il JSON in programmazione non lo fornisce per singolo film.', 80),
('dashboard_contest', 'Contest', 'Qui configuri le edizioni del contest di questo profilo (nome, date, regolamento) e gestisci le candidature, i gruppi, i voti e gli sponsor. La pagina pubblica di ogni edizione è `/{slug}/contest/indirizzo`; l''elenco delle edizioni è /{slug}/contest. Un artista candida un solo brano; il brano deve essere su Spotify e uscito entro il numero di mesi indicato prima dell''inizio delle votazioni. Una candidatura resta «in attesa» finché non la approvi: all''approvazione l''artista riceve la conferma e il brano entra nella lista ufficiale.', NULL, 90),
('dashboard_fan_actors', 'Attori che amo', 'Cerca attori e attrici (catalogo TMDb) e aggiungili alla tua lista — chiunque esista su TMDb, non solo persone registrate su {site_name}. Comparirà sulla tua pagina pubblica come vetrina di ciò che ami guardare. La ricerca parte da sola mentre scrivi, e aggiungere/rimuovere un attore aggiorna la lista all''istante, senza ricaricare la pagina.', 'Ogni attore aggiunto ha una sua pagina pubblica dedicata (raggiungibile cliccandoci sopra), condivisibile sui social con anteprima immagine/testo. Da "✏️ Gestisci pubblicazione" puoi scrivere perché ti piace (anche con l''aiuto dell''AI), aggiungere una foto, decidere se deve comparire nel Feed (Pubblico/Solo io), programmarne la comparsa per una data futura e impostare il link personalizzato per il feed — stessa logica della Timeline.

Ogni nuovo elemento aggiunto parte impostato su **Solo io**: resta visibile nella tua lista e nella sua pagina, ma compare nel Feed solo dopo che lo confermi come Pubblico da "✏️ Gestisci pubblicazione".', 100),
('dashboard_fan_albums', 'Album che amo', 'Cerca album (e singoli) su Spotify e aggiungili alla tua lista — qualsiasi album esista su Spotify. Comparirà sulla tua pagina pubblica come vetrina di ciò che ami ascoltare. La ricerca parte da sola mentre scrivi, e aggiungere/rimuovere un album aggiorna la lista all''istante, senza ricaricare la pagina.', 'Ogni album aggiunto ha una sua pagina pubblica dedicata (raggiungibile cliccandoci sopra), condivisibile sui social con anteprima immagine/testo. Da "✏️ Gestisci pubblicazione" puoi scrivere perché ti piace (anche con l''aiuto dell''AI), aggiungere una foto, decidere se deve comparire nel Feed (Pubblico/Solo io), programmarne la comparsa per una data futura e impostare il link personalizzato per il feed — stessa logica della Timeline.

Ogni nuovo elemento aggiunto parte impostato su **Solo io**: resta visibile nella tua lista e nella sua pagina, ma compare nel Feed solo dopo che lo confermi come Pubblico da "✏️ Gestisci pubblicazione".', 110),
('dashboard_fan_bands', 'Band che amo', 'Cerca su Spotify le band o gli artisti che ami e aggiungili alla tua lista — qualsiasi band esista su Spotify, non solo quelle registrate su {site_name}. Comparirà sulla tua pagina pubblica come vetrina di ciò che ascolti. La ricerca parte da sola mentre scrivi, e aggiungere/rimuovere una band aggiorna la lista all''istante, senza ricaricare la pagina.', 'Ogni band aggiunta ha una sua pagina pubblica dedicata (raggiungibile cliccandoci sopra), condivisibile sui social con anteprima immagine/testo. Da "✏️ Gestisci pubblicazione" puoi scrivere perché ti piace (anche con l''aiuto dell''AI), aggiungere una foto, decidere se deve comparire nel Feed (Pubblico/Solo io), programmarne la comparsa per una data futura e impostare il link personalizzato per il feed — stessa logica della Timeline.

Ogni nuovo elemento aggiunto parte impostato su **Solo io**: resta visibile nella tua lista e nella sua pagina, ma compare nel Feed solo dopo che lo confermi come Pubblico da "✏️ Gestisci pubblicazione".', 120),
('dashboard_fan_books', 'Libri che amo', 'Cerca libri (catalogo Google Books) e aggiungili alla tua lista — qualsiasi libro esista su Google Books. Comparirà sulla tua pagina pubblica come vetrina di ciò che ami leggere. La ricerca parte da sola mentre scrivi, e aggiungere/rimuovere un libro aggiorna la lista all''istante, senza ricaricare la pagina.', 'Ogni libro aggiunto ha una sua pagina pubblica dedicata (raggiungibile cliccandoci sopra), condivisibile sui social con anteprima immagine/testo. Da "✏️ Gestisci pubblicazione" puoi scrivere perché ti piace (anche con l''aiuto dell''AI), aggiungere una foto, decidere se deve comparire nel Feed (Pubblico/Solo io), programmarne la comparsa per una data futura e impostare il link personalizzato per il feed — stessa logica della Timeline.

Ogni nuovo elemento aggiunto parte impostato su **Solo io**: resta visibile nella tua lista e nella sua pagina, ma compare nel Feed solo dopo che lo confermi come Pubblico da "✏️ Gestisci pubblicazione".', 130),
('dashboard_fan_matches', 'Partite che amo', 'TheSportsDB non permette di cercare una partita per nome: prima cerca e scegli una squadra, poi scegli una partita dal suo calendario (prossime partite in programma e ultime giocate). Comparirà sulla tua pagina pubblica come vetrina di ciò che ami seguire, con risultato (se già giocata), campionato, stadio e data.', 'Ogni partita aggiunta ha una sua pagina pubblica dedicata (raggiungibile cliccandoci sopra), condivisibile sui social con anteprima immagine/testo. Da "✏️ Gestisci pubblicazione" puoi scrivere perché ti piace (anche con l''aiuto dell''AI), aggiungere una foto, decidere se deve comparire nel Feed (Pubblico/Solo io), programmarne la comparsa per una data futura e impostare il link personalizzato per il feed — stessa logica della Timeline.

Ogni nuovo elemento aggiunto parte impostato su **Solo io**: resta visibile nella tua lista e nella sua pagina, ma compare nel Feed solo dopo che lo confermi come Pubblico da "✏️ Gestisci pubblicazione".', 140),
('dashboard_fan_movies', 'Film che amo', 'Cerca film (catalogo TMDb) e aggiungili alla tua lista — qualsiasi film esista su TMDb. Comparirà sulla tua pagina pubblica come vetrina di ciò che ami guardare. La ricerca parte da sola mentre scrivi, e aggiungere/rimuovere un film aggiorna la lista all''istante, senza ricaricare la pagina.', 'Ogni film aggiunto ha una sua pagina pubblica dedicata (raggiungibile cliccandoci sopra), condivisibile sui social con anteprima immagine/testo. Da "✏️ Gestisci pubblicazione" puoi scrivere perché ti piace (anche con l''aiuto dell''AI), aggiungere una foto, decidere se deve comparire nel Feed (Pubblico/Solo io), programmarne la comparsa per una data futura e impostare il link personalizzato per il feed — stessa logica della Timeline.

Ogni nuovo elemento aggiunto parte impostato su **Solo io**: resta visibile nella tua lista e nella sua pagina, ma compare nel Feed solo dopo che lo confermi come Pubblico da "✏️ Gestisci pubblicazione".', 150),
('dashboard_fan_players', 'Calciatori che amo', 'Cerca calciatori su TheSportsDB e aggiungili alla tua lista — qualsiasi calciatore del suo catalogo. Comparirà sulla tua pagina pubblica come vetrina di ciò che ami seguire, con squadra, ruolo, nazionalità e data di nascita. La ricerca parte da sola mentre scrivi, e aggiungere/rimuovere un calciatore aggiorna la lista all''istante, senza ricaricare la pagina.', 'Ogni calciatore aggiunto ha una sua pagina pubblica dedicata (raggiungibile cliccandoci sopra), condivisibile sui social con anteprima immagine/testo. Da "✏️ Gestisci pubblicazione" puoi scrivere perché ti piace (anche con l''aiuto dell''AI), aggiungere una foto, decidere se deve comparire nel Feed (Pubblico/Solo io), programmarne la comparsa per una data futura e impostare il link personalizzato per il feed — stessa logica della Timeline.

Ogni nuovo elemento aggiunto parte impostato su **Solo io**: resta visibile nella tua lista e nella sua pagina, ma compare nel Feed solo dopo che lo confermi come Pubblico da "✏️ Gestisci pubblicazione".', 160),
('dashboard_fan_playlists', 'Playlist che amo', 'Cerca playlist pubbliche su Spotify e aggiungile alla tua lista — qualsiasi playlist pubblica esista su Spotify. Comparirà sulla tua pagina pubblica come vetrina di ciò che ami ascoltare. La ricerca parte da sola mentre scrivi, e aggiungere/rimuovere una playlist aggiorna la lista all''istante, senza ricaricare la pagina.', 'Ogni playlist aggiunta ha una sua pagina pubblica dedicata (raggiungibile cliccandoci sopra), condivisibile sui social con anteprima immagine/testo. Da "✏️ Gestisci pubblicazione" puoi scrivere perché ti piace (anche con l''aiuto dell''AI), aggiungere una foto, decidere se deve comparire nel Feed (Pubblico/Solo io), programmarne la comparsa per una data futura e impostare il link personalizzato per il feed — stessa logica della Timeline.

Ogni nuovo elemento aggiunto parte impostato su **Solo io**: resta visibile nella tua lista e nella sua pagina, ma compare nel Feed solo dopo che lo confermi come Pubblico da "✏️ Gestisci pubblicazione".', 170),
('dashboard_fan_publications', 'Pubblicazioni che amo', 'Cerca pubblicazioni scientifiche/accademiche (catalogo CrossRef — oltre 150 milioni di articoli, atti di convegni e altri lavori indicizzati con DOI) e aggiungile alla tua lista. Comparirà sulla tua pagina pubblica come vetrina di ciò che ami leggere. La ricerca parte da sola mentre scrivi, e aggiungere/rimuovere una pubblicazione aggiorna la lista all''istante, senza ricaricare la pagina.', 'Ogni pubblicazione aggiunta ha una sua pagina pubblica dedicata (raggiungibile cliccandoci sopra), condivisibile sui social con anteprima titolo/testo. Da "✏️ Gestisci pubblicazione" puoi scrivere perché ti interessa (anche con l''aiuto dell''AI), aggiungere una foto, decidere se deve comparire nel Feed (Pubblico/Solo io), programmarne la comparsa per una data futura e impostare il link personalizzato per il feed — stessa logica della Timeline.

Ogni nuovo elemento aggiunto parte impostato su **Solo io**: resta visibile nella tua lista e nella sua pagina, ma compare nel Feed solo dopo che lo confermi come Pubblico da "✏️ Gestisci pubblicazione".', 180),
('dashboard_fan_recipes', 'Ricette che amo', 'Cerca ricette pubbliche su Spoonacular e aggiungile alla tua lista — qualsiasi ricetta del suo catalogo. Comparirà sulla tua pagina pubblica come vetrina di ciò che ami cucinare/ mangiare, con tempo di preparazione, porzioni e ingredienti (tradotti in italiano automaticamente, se l''Assistente AI è configurato). La ricerca parte da sola mentre scrivi, e aggiungere/rimuovere una ricetta aggiorna la lista all''istante, senza ricaricare la pagina.', 'Ogni ricetta aggiunta ha una sua pagina pubblica dedicata (raggiungibile cliccandoci sopra), condivisibile sui social con anteprima immagine/testo. Da "✏️ Gestisci pubblicazione" puoi scrivere perché ti piace (anche con l''aiuto dell''AI), aggiungere una foto, decidere se deve comparire nel Feed (Pubblico/Solo io), programmarne la comparsa per una data futura e impostare il link personalizzato per il feed — stessa logica della Timeline.

Ogni nuovo elemento aggiunto parte impostato su **Solo io**: resta visibile nella tua lista e nella sua pagina, ma compare nel Feed solo dopo che lo confermi come Pubblico da "✏️ Gestisci pubblicazione".', 190),
('dashboard_fan_teams', 'Squadre che amo', 'Cerca squadre sportive su TheSportsDB e aggiungile alla tua lista — qualsiasi squadra del suo catalogo. Comparirà sulla tua pagina pubblica come vetrina di ciò che ami seguire, con campionato, paese, stadio e la prossima partita in programma. La ricerca parte da sola mentre scrivi, e aggiungere/rimuovere una squadra aggiorna la lista all''istante, senza ricaricare la pagina.', 'Ogni squadra aggiunta ha una sua pagina pubblica dedicata (raggiungibile cliccandoci sopra), condivisibile sui social con anteprima immagine/testo. Da "✏️ Gestisci pubblicazione" puoi scrivere perché ti piace (anche con l''aiuto dell''AI), aggiungere una foto, decidere se deve comparire nel Feed (Pubblico/Solo io), programmarne la comparsa per una data futura e impostare il link personalizzato per il feed — stessa logica della Timeline.

Ogni nuovo elemento aggiunto parte impostato su **Solo io**: resta visibile nella tua lista e nella sua pagina, ma compare nel Feed solo dopo che lo confermi come Pubblico da "✏️ Gestisci pubblicazione".', 200),
('dashboard_fan_trips', 'Viaggi', 'Cerca un luogo (via OpenStreetMap, gratuito) o inserisci le coordinate a mano se non lo trovi, e aggiungilo alla tua lista di viaggi. Comparirà sulla tua pagina pubblica come diario dei posti che hai visitato.', 'Il nome trovato dalla ricerca è sempre modificabile prima di aggiungere il punto — utile perché la mappa spesso trova l''indirizzo esatto ma non il nome del locale (es. "Via Roma 12" invece di "Trattoria da Mario"). Puoi correggerlo anche in seguito da "✏️ Gestisci pubblicazione".

Ogni viaggio aggiunto ha una sua pagina pubblica dedicata (raggiungibile cliccandoci sopra), con una mappa e condivisibile sui social. Da "✏️ Gestisci pubblicazione" puoi scrivere il racconto (anche con l''aiuto dell''AI), aggiungere una foto, decidere se deve comparire nel Feed (Pubblico/Solo io), programmarne la comparsa per una data futura e impostare il link personalizzato per il feed — stessa logica della Timeline.

Se non carichi una foto tua, l''anteprima social usa automaticamente una miniatura della mappa del posto, così ogni viaggio ha sempre un''immagine condivisibile.

Ogni nuovo elemento aggiunto parte impostato su **Solo io**: resta visibile nella tua lista e nella sua pagina, ma compare nel Feed solo dopo che lo confermi come Pubblico da "✏️ Gestisci pubblicazione".', 210),
('dashboard_followers', 'Follower', 'I visitatori della tua pagina pubblica possono iscriversi lasciando la propria email (con doppia conferma anti-spam). Quando pubblichi un nuovo articolo sul blog o un nuovo concerto, i tuoi follower ricevono automaticamente una notifica via email.', NULL, 220),
('dashboard_following', 'Seguiti', 'L''elenco dei profili che segui — i loro contenuti compaiono nella tua Timeline personale. Per seguire un nuovo profilo, vai sulla sua pagina pubblica e clicca "Segui".', NULL, 230),
('dashboard_invite', 'Invita', 'Condividi il tuo link personale con chi vuoi invitare su {site_name} — chi lo apre può registrarsi subito, nessuna approvazione necessaria. Appena completa la registrazione, inizierete a seguirvi a vicenda automaticamente.', NULL, 240),
('dashboard_links', 'Link', 'Aggiungi qui i pulsanti del tuo Link in Bio: social, sito web, streaming, qualsiasi link tu voglia mostrare. Le icone dei servizi più comuni (Spotify, Instagram, YouTube, ecc.) vengono riconosciute automaticamente e mostrate in cima alla pagina pubblica come icone social invece che come pulsanti — usa le frecce per decidere l''ordine dei link rimanenti.', 'Il **Tasto Speciale** qui sotto genera in automatico un pulsante per ogni sezione del sito che hai già popolato con contenuti (Timeline, Che Amo, Blog, Eventi, Offerte, ecc.), raggruppati dietro un separatore "Sezioni del sito". Puoi premerlo quando vuoi: non duplica nulla, aggiorna i pulsanti già creati e rimuove quelli delle sezioni che restano senza contenuti.', 250),
('dashboard_log', 'Log', 'Il registro si attiva automaticamente quando condividi la gestione del profilo con almeno un''altra persona (Team e co-admin) — da quel momento, ogni azione fatta da un co-admin (aggiornamenti in Timeline, nuovi brani, ecc.) viene registrata qui, con nome di chi l''ha fatta e quando.', NULL, 260),
('dashboard_menu', 'Menù', 'Organizza il tuo menù in categorie (es. Antipasti, Primi, Dolci) e aggiungi i piatti con prezzo e, se vuoi, gli allergeni previsti dalla normativa UE. La tua pagina pubblica mostrerà il menù completo, diviso per categoria, sotto `/{slug}/menu`.', NULL, 270),
('dashboard_messages', 'Messaggi', 'Puoi scrivere solo con chi ti segue e che segui a tua volta — nessun messaggio con sconosciuti. Chi riceve il tuo primo messaggio della giornata riceve un''email di notifica (senza mai rivelare il contenuto), al massimo una volta al giorno.', NULL, 280),
('dashboard_metricool', 'Social Automatico', 'Quando pubblichi un post Timeline o un articolo Blog, il contenuto viene aggiunto a una coda. Ogni 10 minuti, Claude legge la coda, genera una **copy ottimizzata per ogni social network** (tono, lunghezza, hashtag diversi per Instagram, Facebook, LinkedIn, ecc.) e la schedula su Metricool. Nessun intervento manuale richiesto.', 'Per ogni profilo serve l''**ID Metricool** del brand collegato: lo inserisce l''amministratore del sito. Poi scegli su quali social pubblicare.', 290),
('dashboard_nav_menu', 'Menu di Navigazione', 'Scegli quali voci mostrare nel menu di navigazione della tua pagina pubblica — anche Spotify, Podcast, YouTube e il pulsante "Segui". Band/Attori/Film/Libri/Playlist/Album che amo non hanno più un tab a testa in cima alla pagina: sono raccolti dentro "Che Amo", e la spunta qui sotto decide se compaiono come card in quella vetrina. Restano comunque raggiungibili con un link diretto e condivisibile (es. `/tuoslug/film-che-amo`), come indicato accanto a ciascuna voce. Nota: Spotify/Podcast/YouTube/Menù/Offerte/Foto/Servizi/Band/Attori/Film/Libri/Playlist/Album che amo/Viaggi restano comunque visibili solo se hanno anche effettivamente del contenuto PUBBLICO (collegamento fatto, piatti attivi, elementi aggiunti, offerta/album/servizio con visibilità "Pubblico" e non programmato nel futuro) — spuntarli qui non basta da solo a farli comparire: qui sotto trovi segnalato quali, fra quelle già spuntate, ne sono ancora prive. Trascina una voce dall''icona per cambiarne l''ordine: si salva subito, senza bisogno di premere "Salva".', NULL, 300),
('dashboard_offers', 'Offerte speciali', 'Promozioni e sconti mostrati sulla tua pagina pubblica, in una sezione dedicata "Offerte" (compare solo se hai almeno un''offerta attiva e valida). Ognuna ha anche una pagina propria condivisibile sui social, con anteprima corretta (immagine, titolo, descrizione).', 'La validità è facoltativa: lasciala vuota per un''offerta sempre attiva, oppure imposta un inizio e/o una fine — fuori da quell''intervallo l''offerta smette automaticamente di comparire lato pubblico (resta comunque qui, puoi riattivarla cambiando le date). Il pulsante Attiva/Disattiva sospende un''offerta manualmente, senza doverla eliminare.

Il pulsante **✨ Genera con AI** scrive una bozza di descrizione a partire da poche parole chiave: scrivi cosa vuoi comunicare, l''AI propone un testo pronto che puoi modificare liberamente prima di salvare.', 310),
('dashboard_podcast', 'Podcast', 'Se hai un podcast su Spotify, cercalo qui e collegalo: la tua pagina pubblica mostrerà automaticamente gli episodi più recenti in una sezione dedicata, aggiornata direttamente da Spotify.', NULL, 320),
('dashboard_post', 'Timeline', 'Un modo rapido per condividere un pensiero, un annuncio breve, o una foto — senza dover scrivere un articolo completo come nel Blog. Puoi renderlo pubblico o visibile solo a te, e programmarne la pubblicazione per una data futura.', 'Il link personalizzato per il feed è opzionale: se lo compili, chi clicca sui post pubblicati **da questo momento in poi** (dalla Timeline, dal feed RSS o da un''automazione tipo Metricool) viene reindirizzato lì invece che alla pagina del post su {site_name}. Il feed RSS continua comunque a esporre il permalink standard e l''immagine caricata qui, per restare compatibile con strumenti come Metricool. Vale finché non lo modifichi o lo svuoti — non serve ripeterlo a ogni pubblicazione.

Il pulsante **✨ Genera con AI** scrive una bozza di testo a partire da poche parole chiave: scrivi cosa vuoi comunicare, l''AI propone un testo pronto che puoi modificare liberamente prima di pubblicare.', 330),
('dashboard_products', 'Catalogo prodotti', 'Scegli il tipo di feed (Google Shopping / PrestaShop oppure WooCommerce), incolla l''URL e premi **Aggiorna prodotti**: vengono importati nome, descrizione, prezzo di listino e scontato, link alla pagina e immagine principale. Le immagini **non** vengono scaricate: si salva solo il loro indirizzo. Le taglie sono ignorate (un prodotto per modello). Un prodotto che sparisce dal feed viene nascosto, non cancellato. L''aggiornamento è solo manuale. I prodotti sono poi disponibili agli strumenti MCP per programmare i post social.', NULL, 340),
('dashboard_profiles', 'I tuoi profili', 'Crea qui altri profili pubblici (pagine) gestiti dallo stesso tuo account — utile ad esempio se segui più attività diverse. Ogni profilo ha la propria pagina pubblica, i propri link, eventi, blog, ecc., del tutto separati dagli altri. Passa dall''uno all''altro con il selettore in alto nella dashboard (l''icona accanto al menu account).', NULL, 350),
('dashboard_reservations', 'Prenotazioni', 'Le prenotazioni arrivano dagli eventi per cui hai attivato "Accetta prenotazioni" (da Eventi). Qui puoi vedere le singole richieste ed anche i tuoi clienti — chi ha già prenotato almeno una volta, con l''email e il telefono lasciati, per poterli ricontattare quando vuoi.', NULL, 360),
('dashboard_schedule', 'Programmati', 'Tutti i contenuti che hai programmato per una data futura — Timeline, Blog, ogni modulo Che Amo, Offerte, Album, Servizi — raccolti qui in un unico calendario, dal più vicino al più lontano. Da "Modifica" apri direttamente la pagina di gestione di quell''elemento per cambiare testo o data. Gli Eventi non compaiono: la loro data è quando si terranno, non una programmazione di pubblicazione.', '"Copia" e "Anteprima" usano lo stesso link riservato alla pagina pubblica di quel contenuto, valido anche se non è ancora pubblico: "Anteprima" la apre subito in una nuova scheda, "Copia" mette il link negli appunti — utile per controllarlo prima della pubblicazione o per incollarlo nel Tool di Meta per le Anteprime social (Sharing Debugger).', 370),
('dashboard_services', 'Servizi', 'Illustra i servizi della tua attività: foto, titolo, descrizione e una galleria fotografica a carosello (fino a {service_max_photos} foto). Il pulsante "Richiedi informazioni" lato pubblico si può attivare o disattivare per ciascun servizio — quando è attivo, chi lo compila ti arriva via email e nella scheda "Richieste" qui sotto.', 'Il pulsante **✨ Genera con AI** scrive una bozza di descrizione a partire da poche parole chiave: scrivi cosa vuoi comunicare, l''AI propone un testo pronto che puoi modificare liberamente prima di salvare.', 380),
('dashboard_spotify', 'Spotify', 'Cerca il tuo nome artista su Spotify e seleziona il profilo giusto: la tua pagina pubblica mostrerà automaticamente una sezione dedicata con i tuoi album, singoli e brani più ascoltati, aggiornata direttamente da Spotify.', NULL, 390),
('dashboard_team', 'Team e co-admin', 'Puoi condividere la gestione di questo profilo con chi già ti segue — un co-admin può pubblicare in Timeline e gestire Brani che amo, ma non può cambiare password, tipo di account, tema grafico, eliminare il profilo, o gestire altri admin: quello resta sempre riservato solo a te. Puoi revocare l''accesso in qualsiasi momento.', NULL, 400),
('dashboard_telegram', 'Telegram', 'Collega il tuo account Telegram al profilo: dopo potrai inviare una foto (con o senza testo) direttamente al bot in chat privata. Il bot ti chiederà se pubblicarla sulla **Timeline** o sul **Blog**, e creerà il post automaticamente.', NULL, 410),
('dashboard_theme', 'Tema grafico', 'Scegli l''aspetto grafico della tua pagina pubblica — il colore che hai scelto in "Profilo" resta il tuo accento personale in ogni tema, cambia solo lo stile generale (sfondo, forme, atmosfera).', NULL, 420),
('dashboard_videos', 'Video', 'Carica i tuoi video (MP4, MOV o WebM, fino a {max_video_mb} MB ciascuno) e dai a ciascuno un titolo e una descrizione. Compaiono nella sezione pubblica "Video" del tuo profilo, ognuno con la sua pagina condivisibile. Puoi selezionarne più d''uno insieme: vengono caricati uno alla volta.', 'Pubblico/Solo io e la programmazione funzionano come nel resto del sito. Se hai attivato "Social Automatico", un video pubblicato subito viene messo in coda per Metricool con titolo, descrizione e file. L''anteprima è presa dal video stesso.', 430),
('dashboard_youtube', 'YouTube', 'Incolla il link del tuo canale YouTube (es. `https://www.youtube.com/@tuoband` o `https://www.youtube.com/channel/UC...`): la tua pagina pubblica mostrerà automaticamente i video più recenti, aggiornati direttamente da YouTube.', NULL, 440);
